async function main(): Promise<void> {
  const ordinaryHelp = execFileSync(process.execPath, [CLI, 'help', '--full'], {
    cwd: process.cwd(),
    encoding: 'utf8',
    env: { ...process.env, LATTICE_BRIEF_OUTPUT: '0' },
