      }, brokerKeys.privateKey);
      const result = verifyNativeReviewInvocationAttestation({
        attestation: swapped,
        trustedBrokers: [{
          brokerId: 'smoke-codex-broker',
          adapterId: 'codex-desktop',
          host: 'codex',
